#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (n == 1) {
        printf("1\n");
        return 0;
    }
    if (n == 2) {
        printf("-1\n");
        return 0;
    }

    long long t = (long long)n * (n - 1) / 2;
    long long m = t + 1;

    for (int i = 0; i < n; i++) {
        long long a = (i == n - 1) ? t : i + 1;
        for (int j = 0; j < n; j++) {
            long long b = (j == n - 1) ? t : j + 1;
            printf("%s%lld", j ? " " : "", m * a + b);
        }
        printf("\n");
    }

    return 0;
}
