        printf("-1\n");
        return 0;
    }

    if (N % 2 == 1) {
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                if (j) printf(" ");
                printf("%d", i * N + j + 1);
            }
            printf("\n");
        }
    } else {
        int X = (N - 2) * (N + 1) / 2;
        int D = X + 1;

        for (int i = 0; i < N; ++i) {
            int start = (i < N - 1) ? 1 + i * D : 1 + X * D;
            for (int j = 0; j < N; ++j) {
                if (j) printf(" ");
                printf("%d", start + (j < N - 1 ? j : X));
            }
            printf("\n");
        }
